    { id: 3, jobSeekerId: 3, jobSeekerName: 'Meera Nair',   jobId: 12, jobTitle: 'Product Designer',    companyName: 'Fernwood Labs',   status: 'APPROVED', appliedDate: new Date('2026-06-18') },
